module tb_TopModule;
  logic clk;
  logic in;
  logic out;

  TopModule dut (
    .clk(clk),
    .in(in),
    .out(out)
  );

  always #5 clk = ~clk;

  // Behavioral model for checking
  logic expected_out;

  initial begin
    clk = 0;
    in = 0;
    // Force initial state of DFF for predictable simulation starting point
    // (since hardware without reset has indeterminate startup, but in sim we can initialize or force)
    force dut.out = 1'b0;
    expected_out = 1'b0;
    #2;
    release dut.out;

    // Test sequence
    // Cycle 1: in=0, expected_out = 0 ^ 0 = 0
    in = 0;
    @(posedge clk);
    #1;
    expected_out = in ^ expected_out;
    if (out !== expected_out) begin
      $display("SELFTEST FAIL: at t=%0t, expected %b, got %b", $time, expected_out, out);
      $finish;
    end

    // Cycle 2: in=1, expected_out = 1 ^ 0 = 1
    in = 1;
    @(posedge clk);
    #1;
    expected_out = in ^ expected_out;
    if (out !== expected_out) begin
      $display("SELFTEST FAIL: at t=%0t, expected %b, got %b", $time, expected_out, out);
      $finish;
    end

    // Cycle 3: in=1, expected_out = 1 ^ 1 = 0
    in = 1;
    @(posedge clk);
    #1;
    expected_out = in ^ expected_out;
    if (out !== expected_out) begin
      $display("SELFTEST FAIL: at t=%0t, expected %b, got %b", $time, expected_out, out);
      $finish;
    end

    // Cycle 4: in=0, expected_out = 0 ^ 0 = 0
    in = 0;
    @(posedge clk);
    #1;
    expected_out = in ^ expected_out;
    if (out !== expected_out) begin
      $display("SELFTEST FAIL: at t=%0t, expected %b, got %b", $time, expected_out, out);
      $finish;
    end

    // Cycle 5: in=1, expected_out = 1 ^ 0 = 1
    in = 1;
    @(posedge clk);
    #1;
    expected_out = in ^ expected_out;
    if (out !== expected_out) begin
      $display("SELFTEST FAIL: at t=%0t, expected %b, got %b", $time, expected_out, out);
      $finish;
    end

    $display("SELFTEST PASS");
    $finish;
  end

endmodule
